package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.TokenEndpointAuthSigningAlgVO;

class TokenEndpointAuthSigningAlgValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of token endpoint auth signing alg of oauth client")
  void test_token_endpoint_auth_signing_alg_value_holder_assign_plain_value() {
    Object holder = new Object();
    TokenEndpointAuthSigningAlgValueHolder<Object> value =
        new TokenEndpointAuthSigningAlgValueHolder<>(holder);
    Assertions.assertSame(holder, value.tokenEndpointAuthSigningAlg("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getTokenEndpointAuthSigningAlgValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getTokenEndpointAuthSigningAlg().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.tokenEndpointAuthSigningAlgNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getTokenEndpointAuthSigningAlgValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getTokenEndpointAuthSigningAlg().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of token endpoint auth signing alg of oauth client")
  void test_token_endpoint_auth_signing_alg_value_holder_assign_value_object() {
    Object holder = new Object();
    TokenEndpointAuthSigningAlgValueHolder<Object> value =
        new TokenEndpointAuthSigningAlgValueHolder<>(holder);
    TokenEndpointAuthSigningAlgVO vo = TokenEndpointAuthSigningAlgVO.from("one");
    Assertions.assertFalse(value.getTokenEndpointAuthSigningAlgValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.tokenEndpointAuthSigningAlg(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getTokenEndpointAuthSigningAlgValue().orElseThrow());
    Assertions.assertSame(holder, value.tokenEndpointAuthSigningAlg(Optional.empty()));
    Assertions.assertFalse(value.getTokenEndpointAuthSigningAlgValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.tokenEndpointAuthSigningAlg(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTokenEndpointAuthSigningAlgValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of token endpoint auth signing alg of oauth client against the original")
  void test_token_endpoint_auth_signing_alg_value_holder_read() {
    Object holder = new Object();
    TokenEndpointAuthSigningAlgValueHolder<Object> value =
        new TokenEndpointAuthSigningAlgValueHolder<>(holder);
    TokenEndpointAuthSigningAlgVO vo = TokenEndpointAuthSigningAlgVO.from("one");
    TokenEndpointAuthSigningAlgVO other = TokenEndpointAuthSigningAlgVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getTokenEndpointAuthSigningAlgValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other,
        value.readTokenEndpointAuthSigningAlg(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readTokenEndpointAuthSigningAlg(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.tokenEndpointAuthSigningAlg(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTokenEndpointAuthSigningAlg(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTokenEndpointAuthSigningAlg(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of token endpoint auth signing alg of oauth client")
  void test_token_endpoint_auth_signing_alg_value_holder_unset() {
    Object holder = new Object();
    TokenEndpointAuthSigningAlgValueHolder<Object> value =
        new TokenEndpointAuthSigningAlgValueHolder<>(holder);
    TokenEndpointAuthSigningAlgVO vo = TokenEndpointAuthSigningAlgVO.from("one");
    value.tokenEndpointAuthSigningAlg(vo);
    Assertions.assertSame(holder,
        value.unsetTokenEndpointAuthSigningAlgIfMatches("tokenEndpointAuthSigningAlg_other"));
    Assertions.assertTrue(value.getTokenEndpointAuthSigningAlgValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetTokenEndpointAuthSigningAlgIfMatches("tokenEndpointAuthSigningAlg"));
    Assertions.assertFalse(value.getTokenEndpointAuthSigningAlgValue().isPresent(),
        "The field name must clear the value");
    value.tokenEndpointAuthSigningAlg(vo);
    Assertions.assertSame(holder, value.unsetTokenEndpointAuthSigningAlg());
    Assertions.assertFalse(value.getTokenEndpointAuthSigningAlgValue().isPresent(),
        "Unset must clear the value");
  }
}
